const pad=n=>String(n).padStart(2,'0');
export function openDatePicker(input){
 const timeOnly=input.type==='time',dateOnly=input.type==='date',now=new Date(),initial=input.value||(timeOnly?pad(now.getHours())+':'+pad(now.getMinutes()):now.getFullYear()+'-'+pad(now.getMonth()+1)+'-'+pad(now.getDate())+'T'+pad(now.getHours())+':'+pad(now.getMinutes()));
 const date=timeOnly?null:new Date(initial.length===10?initial+'T12:00':initial),chosen={year:date?.getFullYear()||now.getFullYear(),month:(date?.getMonth()??now.getMonth())+1,day:date?.getDate()||now.getDate(),hour:Number((timeOnly?initial:initial.split('T')[1]||'12:00').slice(0,2)),minute:Number((timeOnly?initial:initial.split('T')[1]||'12:00').slice(3,5))};
 const overlay=document.createElement('div');overlay.className='dt-overlay';overlay.innerHTML='<section class="dt-sheet" role="dialog" aria-modal="true" aria-label="'+(input.getAttribute('aria-label')||'调整时间')+'"><header><button type="button" data-cancel>取消</button><strong>'+(timeOnly?'选择时间':dateOnly?'选择日期':'选择日期和时间')+'</strong><button type="button" data-confirm>确定</button></header><div class="dt-wheels"></div><p class="dt-error" role="alert"></p></section>';document.body.append(overlay);
 const wheels=overlay.querySelector('.dt-wheels'),previous=document.activeElement,timers=[],columns=new Map();
 const refresh=()=>{const max=new Date(chosen.year,chosen.month,0).getDate();chosen.day=Math.min(chosen.day,max);const column=columns.get('day');if(column&&column.count!==max){populate(column,max);column.list.scrollTop=(chosen.day-1)*40;}};
 const populate=(column,count)=>{column.count=count;column.list.innerHTML=Array.from({length:count},(_,i)=>'<button type="button" role="option" aria-selected="false" data-value="'+(i+column.start)+'">'+(column.key==='year'?i+column.start:pad(i+column.start))+'</button>').join('');column.list.querySelectorAll('button').forEach(button=>button.onclick=()=>{chosen[column.key]=Number(button.dataset.value);column.list.scrollTo({top:(chosen[column.key]-column.start)*40,behavior:'instant'});mark(column);refresh();});mark(column);};
 const mark=column=>column.list.querySelectorAll('button').forEach(button=>button.setAttribute('aria-selected',String(Number(button.dataset.value)===chosen[column.key])));
 const add=(key,title,start,count)=>{const wrapper=document.createElement('div');wrapper.className='dt-column';wrapper.innerHTML='<small>'+title+'</small><div class="dt-wheel" role="listbox" aria-label="'+title+'" tabindex="0"></div>';wheels.append(wrapper);const column={key,start,count,list:wrapper.lastElementChild};columns.set(key,column);populate(column,count);column.list.scrollTop=(chosen[key]-start)*40;let timer;column.list.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>{chosen[key]=Math.min(start+column.count-1,Math.max(start,Math.round(column.list.scrollTop/40)+start));mark(column);refresh();},90);timers.push(()=>clearTimeout(timer));});column.list.onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();chosen[key]=Math.min(start+column.count-1,Math.max(start,chosen[key]+(e.key==='ArrowDown'?1:-1)));column.list.scrollTo({top:(chosen[key]-start)*40,behavior:'instant'});mark(column);refresh();}};};
 if(!timeOnly){add('year','年',Math.min(2000,chosen.year),Math.max(2100,chosen.year)-Math.min(2000,chosen.year)+1);add('month','月',1,12);add('day','日',1,new Date(chosen.year,chosen.month,0).getDate());}if(!dateOnly){add('hour','时',0,24);add('minute','分',0,60);}
 const close=()=>{timers.forEach(stop=>stop());overlay.remove();previous?.focus();};
 overlay.querySelector('[data-cancel]').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('header button,.dt-wheel')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}}};
 overlay.querySelector('[data-confirm]').onclick=()=>{for(const column of columns.values()){chosen[column.key]=Math.min(column.start+column.count-1,Math.max(column.start,Math.round(column.list.scrollTop/40)+column.start));}refresh();const d=chosen.year+'-'+pad(chosen.month)+'-'+pad(chosen.day),t=pad(chosen.hour)+':'+pad(chosen.minute),value=timeOnly?t:dateOnly?d:d+'T'+t;if((input.min&&value<input.min)||(input.max&&value>input.max)){overlay.querySelector('.dt-error').textContent='请选择允许范围内的日期和时间';return;}input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));close();};overlay.querySelector('[data-confirm]').focus();
}
export function bindDatePickers(){
 document.querySelectorAll('#scheduleForm input[name=at],#completionForm input[name=date],#completionForm input[name=time],#recordForm input[type="datetime-local"],#recordForm input[type="date"],#recordForm input[type="time"]').forEach(input=>{const host=input.closest('label');if(!host)return;host.style.position='relative';input.tabIndex=-1;input.classList.add('dt-native');const trigger=document.createElement('button');trigger.type='button';trigger.className='dt-trigger';trigger.setAttribute('aria-label','调整'+(input.getAttribute('aria-label')||'时间'));trigger.onclick=e=>{e.preventDefault();openDatePicker(input);};host.append(trigger);});
 const next=document.querySelector('#completionForm [name=nextAt]');if(next){document.querySelector('#adjustNext').onclick=()=>openDatePicker(next);document.querySelector('#nextDate').onclick=()=>openDatePicker(next);}
}


